    .map(Trade::getSymbol)
    .collect(Collectors.toList());  // mutable ArrayList!
mutable.add("NEW");  // (Recommended) works — but dangerous for shared state!

// ═══ UNMODIFIABLE SET and MAP ═══
Set<String> unmodSet = trades.stream()
    .map(Trade::getSymbol)
    .collect(Collectors.toUnmodifiableSet());

