package com.bank.immutable;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.stream.*;
import static org.assertj.core.api.Assertions.*;

class UnmodifiableCollectTest {

    @Test void toUnmodifiableListThrowsOnMutation() {
        List<String> result = Stream.of("A", "B").collect(Collectors.toUnmodifiableList());
        assertThatThrownBy(() -> result.add("C")).isInstanceOf(UnsupportedOperationException.class);
    }

    @Test void toListJava16IsUnmodifiable() {
        List<String> result = Stream.of("A", "B").toList();
        assertThatThrownBy(() -> result.add("C")).isInstanceOf(UnsupportedOperationException.class);
    }

    @Test void collectToListIsMutable() {
        List<String> result = Stream.of("A", "B").collect(Collectors.toList());
        result.add("C");  // (Recommended) works — mutable!
        assertThat(result).hasSize(3);
    }

    @Test void collectingAndThenWrapsUnmodifiable() {
        List<String> result = Stream.of("A", "B")
            .collect(Collectors.collectingAndThen(Collectors.toList(), Collections::unmodifiableList));
        assertThatThrownBy(() -> result.add("C")).isInstanceOf(UnsupportedOperationException.class);
    }

    @Test void toUnmodifiableListRejectsNull() {
        assertThatThrownBy(() -> Stream.of("A", null, "B").collect(Collectors.toUnmodifiableList()))
            .isInstanceOf(NullPointerException.class);
        // toUnmodifiableList does NOT allow nulls!
    }
}
